find_cheapest_skill.code:
const skills = await (await fetch('/api/skills.json')).json();
const cheapest = skills.filter(s => s.category === 'AI/ML').sort((a,b) => a.price - b.price)[0];
console.log(cheapest.name, cheapest.price);

find_multilingual_skill.code:
const skills = await (await fetch('/api/skills.json')).json();
const zhSkills = skills.filter(s => s.translations && s.translations.zh);
console.log(`${zhSkills.length} skills support Chinese`);

